head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[treeview > M > getCheckedNodes]<br/>CheckBox 가 선택 상태인 트리 아이템의 정보를 객체 배열로 반환합니다.",
    "validation" : [
        "renderType=virtual 이고 트리 아이템이 ItemSet 으로 정의된 경우에 동작합니다.",
        "options(선택) 파라미터로 CheckBox 가 선택된 트리 아이템 중 반환되는 트리 아이템의 조건을 추가 설정합니다.",
        "hierarchy(선택) 조건으로 hierarchy 속성에 의해 반투명 체크 이미지가 표시된 부모 아이템의 포함 여부를 true/false 로 설정합니다.",
        "hierarchy(선택) 조건으로 true 설정 시 반환값에 반투명 체크 이미지가 표시된 부모 아이템을 포함합니다.",
        "hierarchy(선택) 조건으로 미설정 또는 false 설정 시 반환값에 반투명 체크 이미지가 표시된 부모 아이템을 포함합니다.",
        "반환값으로 CheckBox 가 선택된 트리 아이템 중 파라미터 조건을 만족하는 트리 아이템의 정보를 객체 배열로 반환합니다.",
        "반환값은 Breadth-First Search 방식으로 검색됩니다.",        
        "CheckBox 가 선택된 트리 아이템이 없는 경우 빈 배열을 반환합니다.",
        "반환된 객체의 {CheckBox Column ID} 속성 값으로 CheckBox 항목에 설정된 Column 의 ID 를 키값으로 CheckBox 의 선택 여부를 true/false 로 갖습니다.",
        "반환된 객체의 {Depth Column ID} 속성 값으로 Depth 항목에 설정된 Column 의 ID 를 키값으로 트리 아이템의 Depth(단계) 값을 갖습니다.",
        "반환된 객체의 {CheckBoxDisabled Column ID} 속성 값으로 CheckBoxDisabled 항목에 설정된 Column 의 ID 를 키값으로 CheckBox 의 비활성화(disabled) 값을 true/false 로 갖습니다.",
        "반환된 객체의 {Lebel Column ID} 속성 값으로 Label 항목에 설정된 Column 의 ID 를 키값으로 Label 값을 갖습니다.",
        "반환된 객체의 rowStatus 속성 값으로 트리 아이템의 RowStatus 값을 갖습니다.",
        "반환된 객체의 {Value Column ID} 속성 값으로 Value 항목에 설정된 Column 의 ID 를 키값으로 Value 값을 갖습니다.",        
    ]
}



scwin.onpageload = function () {
    wf_body_left.getObj("scwin").createValidation(scwin.tData);	

    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let properties = {            
        showCheckbox : true,            
        hierarchy : true,
        renderType : "virtual",
    }

    let cList = $c.gcm.createCList(properties);  
    let eList = $c.gcm.createEList(["onclick"]);

    let grp_comp = document.querySelector('.tc_group_basic');
    let strTarget = '';
    let strNameSpace = $c.gcm.getNameSpace();

    strTarget += '<w2:treeview ' + strNameSpace + ' ' + cList + ' ' + eList + ' id="" dataType="listed" tooltipGroupClass="false" style="width:200px; height:350px;">';
    strTarget += '<w2:itemset nodeset="data:dlt_Item">';
    strTarget += '<w2:label ref="label"></w2:label>';
    strTarget += '<w2:value ref="value"></w2:value>';
    strTarget += '<w2:depth ref="depth"></w2:depth>';
    strTarget += '<w2:folder ref=""></w2:folder>';
    strTarget += '<w2:checkbox ref="checkbox"></w2:checkbox>';
    strTarget += '<w2:checkboxDisabled ref="disabled"></w2:checkboxDisabled>';
    strTarget += '<w2:image ref=""></w2:image>';
    strTarget += '<w2:iconImage ref=""></w2:iconImage>';
    strTarget += '<w2:selectedImage ref=""></w2:selectedImage>';
    strTarget += '<w2:expandedImage ref=""></w2:expandedImage>';
    strTarget += '<w2:leafImage ref=""></w2:leafImage>';
    strTarget += '</w2:itemset>';
    strTarget += '</w2:treeview>';

    // target 생성
    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "treeview",
        strTarget,
        grp_comp
    );

    target1.expandNode(1, true);
    target1.expandNode(3, true);
    target1.expandNode(6, true);    
}



scwin.btn_getCheckedNodes_onclick = function (e) {   
    let nodes = null;
    let options = par_options.getText();

    if (options == "")
        nodes = target1.getCheckedNodes();
    else 
        nodes = target1.getCheckedNodes({hierarchy:true});

    wf_body_bottom.getObj("scwin").setReturnValue("return object : "+ nodes);

    if (nodes.length > 0) {
        for (var i=0; i < nodes.length; i++) {
            wf_body_bottom.getObj("scwin").setReturnValue("item["+i+"] checkbox : "+ nodes[0].checkbox);
            wf_body_bottom.getObj("scwin").setReturnValue("item["+i+"] depth : "+ nodes[0].depth);
            wf_body_bottom.getObj("scwin").setReturnValue("item["+i+"] disabled : "+ nodes[0].disabled);
            wf_body_bottom.getObj("scwin").setReturnValue("item["+i+"] label : "+ nodes[0].label);
            wf_body_bottom.getObj("scwin").setReturnValue("item["+i+"] rowStatus : "+ nodes[0].rowStatus);
            wf_body_bottom.getObj("scwin").setReturnValue("item["+i+"] value : "+ nodes[0].value);
        }
    }
};



scwin.target1_onclick = function (e) {
    scwin.btn_getCheckedNodes_onclick();
}
